import type { Contracts } from "@mainsail/contracts";

import { blockHeader, blockSerialized } from "./block.js";

// PROPOSAL WITH VALID ROUND

export const payload: Contracts.Crypto.ProposedPayload = {
	block: {
		serialized: blockSerialized,
	},
	lockProof: undefined,
};

export const payloadSerialized = "00" + blockSerialized; // 

export const proposalDataSerializableUnsigned: Contracts.Crypto.ProposalDataSerializableUnsigned = {
	payloadSerialized,
	round: 1,
	validRound: 0,
	validatorIndex: 0,
};

export const proposalSerializedUnsigned = "010000000100000000a8020000" + payloadSerialized + "00"; // 

export const signature =
	"b637d6e62dbae0e87e20a48bc313f2ffcd9beae757a79b6edcee7071d5024568bf2654e76f5fb1be84c9c0bdb9f0d5e914feefd9d1299f86b7e45270a31803dbe8ab14246718d6131268faf3a3daca19a8af59a267159dfc98ce216b1c634751";

export const proposalDataSerializable: Contracts.Crypto.ProposalDataSerializable = {
	...proposalDataSerializableUnsigned,
	signature,
};

export const proposalSerialized = "010000000100000000a8020000" + payloadSerialized + "00" + signature; // 

export const proposalData: Contracts.Crypto.ProposalData = {
	...proposalDataSerializable,
	blockHeader,
	lockProof: undefined,
};
